package br.edu.insper.tarefas;
import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/tasks") public class TaskController {private final TaskService service; public TaskController(TaskService service){this.service=service;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public TaskRequests.Response create(@RequestBody TaskRequests.Create r){return service.create(r);}@GetMapping public List<TaskRequests.Response> list(){return service.list();}@GetMapping("/{id}") public TaskRequests.Response get(@PathVariable Long id){return service.get(id);}@PutMapping("/{id}") public TaskRequests.Response update(@PathVariable Long id,@RequestBody TaskRequests.Update r){return service.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}@ExceptionHandler(IllegalArgumentException.class) @ResponseStatus(HttpStatus.NOT_FOUND) java.util.Map<String,String> error(IllegalArgumentException e){return java.util.Map.of("error",e.getMessage());}}
